def linear_steps(arr, target):
    steps = 0
    for item in arr:
        steps += 1
        if item == target:
            break
    return steps

def binary_steps(arr, target):
    left, right, steps = 0, len(arr) - 1, 0
    while left <= right:
        steps += 1
        mid = (left + right) // 2
        if arr[mid] == target:
            break
        elif target < arr[mid]:
            right = mid - 1
        else:
            left = mid + 1
    return steps

nums = list(range(1_000_000))
print(linear_steps(nums, 999_999), binary_steps(nums, 999_999))
